<script setup>
import {onMounted,reactive,ref} from 'vue';import request from '../api/request';const list=ref([]);const form=reactive({id:null,name:'',sortOrder:0,enabled:true});async function load(){list.value=(await request.get('/categories/admin')).data.data||[]}async function save(){if(form.id)await request.put(`/categories/${form.id}`,form);else await request.post('/categories',form);form.id=null;form.name='';await load()}function edit(c){Object.assign(form,c)}async function remove(id){await request.delete(`/categories/${id}`);await load()}onMounted(load)
</script>
<template><main class="page-shell"><header class="page-heading"><div><div class="section-kicker">CATALOG SETTINGS</div><h1>商品分类管理</h1></div></header><section class="user-center-card category-editor"><form class="profile-form" @submit.prevent="save"><input v-model="form.name" required placeholder="分类名称"/><input v-model.number="form.sortOrder" type="number" placeholder="排序"/><label><input v-model="form.enabled" type="checkbox"/> 启用</label><button class="primary-button">{{form.id?'保存修改':'新增分类'}}</button></form></section><section class="admin-table-card table-scroll"><table class="data-table"><thead><tr><th>ID</th><th>名称</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in list" :key="c.id"><td>{{c.id}}</td><td>{{c.name}}</td><td>{{c.sortOrder}}</td><td>{{c.enabled?'启用':'停用'}}</td><td><button class="secondary-button" @click="edit(c)">编辑</button><button class="danger-button" @click="remove(c.id)">删除</button></td></tr></tbody></table></section></main></template>
